type recordingRoundTripper struct {
	requests []*http.Request
	bodies   []string
	payloads [][]byte
}

func (r *recordingRoundTripper) RoundTrip(req *http.Request) (*http.Response, error) {
	raw := ""
	if req.Body != nil {
		encoded, _ := io.ReadAll(req.Body)
		raw = string(encoded)
	}
	r.requests = append(r.requests, req)
	r.bodies = append(r.bodies, raw)
	payload := r.payloads[min(len(r.requests)-1, len(r.payloads)-1)]
	return &http.Response{
		StatusCode: 200,
		Header:     http.Header{"Content-Type": []string{"application/json"}},
		Body:       io.NopCloser(strings.NewReader(string(payload))),
		Request:    req,
	}, nil
}

func conformanceFixtures(t *testing.T) map[string]json.RawMessage {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("..", "fixtures", "fixtures.json"))
	if err != nil {
		t.Fatalf("reading fixtures: %v", err)
	}
	var parsed struct {
		Envelopes map[string]json.RawMessage `json:"envelopes"`
	}
	if err := json.Unmarshal(raw, &parsed); err != nil {
		t.Fatalf("parsing fixtures: %v", err)
	}
	return parsed.Envelopes
}

func conformanceClient(t *testing.T, payloads ...[]byte) (*Client, *recordingRoundTripper) {
	t.Helper()
	recorder := &recordingRoundTripper{payloads: payloads}
	client, err := New(
		WithAPIKey("sk_zelf_"+strings.Repeat("0", 64)),
		WithMaxRetries(0),
		WithHTTPClient(&http.Client{Transport: recorder}),
	)
	if err != nil {
		t.Fatalf("building client: %v", err)
	}
	return client, recorder
}

// Every generated method must put its request where the spec says it goes.
func TestConformanceRequestMapping(t *testing.T) {
	envelopes := conformanceFixtures(t)
	for _, entry := range conformanceCases {
		t.Run(entry.operation, func(t *testing.T) {
			payload := envelopes[strings.ReplaceAll(entry.operation, ".", "_")]
			client, recorder := conformanceClient(t, payload)

			if _, err := entry.call(client, context.Background(), entry.paramsJSON, entry.bodyJSON); err != nil {
				t.Fatalf("%s: %v", entry.operation, err)
			}
			if len(recorder.requests) != 1 {
				t.Fatalf("%s: expected 1 request, got %d", entry.operation, len(recorder.requests))
			}

			request := recorder.requests[0]
			if request.Method != entry.method {
				t.Errorf("method = %s, want %s", request.Method, entry.method)
			}
			if request.URL.Path != entry.path {
				t.Errorf("path = %s, want %s", request.URL.Path, entry.path)
			}
			values, err := url.ParseQuery(request.URL.RawQuery)
			if err != nil {
				t.Fatalf("parsing query: %v", err)
			}
			for key, want := range entry.query {
				if got := values[key]; !slices.Equal(got, want) {
					t.Errorf("%s sent ?%s=%q, want %q (query was %q)",
						entry.operation, key, got, want, request.URL.RawQuery)
				}
			}
			if len(entry.body) > 0 {
				var sent map[string]any
				if err := json.Unmarshal([]byte(recorder.bodies[0]), &sent); err != nil {
					t.Fatalf("parsing body: %v", err)
				}
				for _, key := range entry.body {
					if _, ok := sent[key]; !ok {
						t.Errorf("%s dropped body field %s", entry.operation, key)
					}
				}
			}
		})
	}
}

// Walking a page must issue the follow-up request its closure builds.
func TestConformancePaging(t *testing.T) {
	envelopes := conformanceFixtures(t)
	for _, entry := range conformanceCases {
		if entry.cardinality != "page" {
			continue
		}
		t.Run(entry.operation, func(t *testing.T) {
			base := envelopes[strings.ReplaceAll(entry.operation, ".", "_")]
			var decoded map[string]any
			if err := json.Unmarshal(base, &decoded); err != nil {
				t.Fatalf("decoding envelope: %v", err)
			}
			decoded["next"] = 2
			first, _ := json.Marshal(decoded)
			decoded["next"] = nil
			decoded["page"] = 2
			second, _ := json.Marshal(decoded)

			client, recorder := conformanceClient(t, first, second)
			result, err := entry.call(client, context.Background(), entry.paramsJSON, entry.bodyJSON)
			if err != nil {
				t.Fatalf("%s: %v", entry.operation, err)
			}
			walked, err := entry.walk(result, context.Background())
			if err != nil {
				t.Fatalf("%s: %v", entry.operation, err)
			}
			if walked == 0 {
				t.Errorf("%s walked no rows", entry.operation)
			}
			if len(recorder.requests) != 2 {
				t.Errorf("%s made %d requests, want 2", entry.operation, len(recorder.requests))
			}
		})
	}
}

// A caller's own key header must not replace or duplicate the client's.
func TestConformanceAPIKeyHeaderSentOnce(t *testing.T) {
	envelopes := conformanceFixtures(t)
	entry := conformanceCases[0]
	payload := envelopes[strings.ReplaceAll(entry.operation, ".", "_")]
	recorder := &recordingRoundTripper{payloads: [][]byte{payload}}
	key := "sk_zelf_" + strings.Repeat("0", 64)
	client, err := New(
		WithAPIKey(key),
		WithMaxRetries(0),
		WithHeader("X-API-Key", "sk_zelf_"+strings.Repeat("9", 64)),
		WithHTTPClient(&http.Client{Transport: recorder}),
	)
	if err != nil {
		t.Fatalf("building client: %v", err)
	}
	if _, err := entry.call(client, context.Background(), entry.paramsJSON, entry.bodyJSON); err != nil {
		t.Fatalf("%s: %v", entry.operation, err)
	}
	if got := recorder.requests[0].Header.Values("x-api-key"); !slices.Equal(got, []string{key}) {
		t.Errorf("x-api-key = %q, want exactly one %q", got, key)
	}
}

// A failing call must surface the error rather than a half-built value.
func TestConformanceErrorPropagation(t *testing.T) {
	for _, entry := range conformanceCases {
		t.Run(entry.operation, func(t *testing.T) {
			recorder := &failingRoundTripper{}
			client, err := New(
				WithAPIKey("sk_zelf_"+strings.Repeat("0", 64)),
				WithMaxRetries(0),
				WithHTTPClient(&http.Client{Transport: recorder}),
			)
			if err != nil {
				t.Fatalf("building client: %v", err)
			}
			if _, err := entry.call(client, context.Background(), entry.paramsJSON, entry.bodyJSON); err == nil {
				t.Errorf("%s swallowed a 500", entry.operation)
			}
		})
	}
}

// Passing nil params must fall back to an empty set rather than panic.
func TestConformanceNilParams(t *testing.T) {
	envelopes := conformanceFixtures(t)
	for _, entry := range conformanceCases {
		if entry.nilCall == nil {
			continue
		}
		t.Run(entry.operation, func(t *testing.T) {
			payload := envelopes[strings.ReplaceAll(entry.operation, ".", "_")]
			client, recorder := conformanceClient(t, payload)
			if _, err := entry.nilCall(client, context.Background(), entry.bodyJSON); err != nil {
				t.Fatalf("%s: %v", entry.operation, err)
			}
			if len(recorder.requests) != 1 {
				t.Fatalf("%s: expected 1 request, got %d", entry.operation, len(recorder.requests))
			}
		})
	}
}

type failingRoundTripper struct{}

func (failingRoundTripper) RoundTrip(req *http.Request) (*http.Response, error) {
	body := `{"log_id":"log_1","timestamp":"2026-01-01T00:00:00Z","error":{"code":"INTERNAL_ERROR","message":"boom","details":{}}}`
	return &http.Response{
		StatusCode: 500,
		Header:     http.Header{"Content-Type": []string{"application/json"}},
		Body:       io.NopCloser(strings.NewReader(body)),
		Request:    req,
	}, nil
}

